const SYSTEME = "Tu rédiges des e-mails pour CountMeIn, une plateforme marocaine qui met en relation bénévoles et associations. Écris en français, tutoie le bénévole, avec un ton chaleureux, simple et concret. Utilise uniquement les informations fournies dans les données : n'invente ni date, ni horaire, ni lieu, ni consigne, ni matériel, ni chiffre. Si une information manque, n'en parle pas. Pas de formule de politesse finale ni de signature (elles sont ajoutées par le gabarit). Au plus un émoji dans tout l'e-mail. Le sujet fait moins de 70 caractères. Tâche : rappeler au bénévole que sa mission commence dans moins de 24 heures. Reprends la date, l'heure et le lieu. Si des compétences sont listées, dis en une phrase qu'elles seront utiles, sans inventer de détail. Demande de prévenir l'association en cas d'empêchement.";
const SCHEMA = {"type": "object", "properties": {"sujet": {"type": "string", "description": "Objet de l'e-mail"}, "titre": {"type": "string", "description": "Titre affiché en haut de l'e-mail (court)"}, "paragraphes": {"type": "array", "items": {"type": "string"}, "description": "2 ou 3 paragraphes courts"}}, "required": ["sujet", "titre", "paragraphes"], "additionalProperties": false};
// Modèle gratuit Google Gemini (clé AI Studio). Pour en changer, modifiez MODELE.
const MODELE = 'gemini-flash-latest';
function requeteIA(donnees) {
  return {
    url: `https://generativelanguage.googleapis.com/v1beta/models/${MODELE}:generateContent`,
    corps: {
      systemInstruction: { parts: [{ text: SYSTEME +
        ' Réponds uniquement avec un objet JSON valide respectant ce schéma : ' + JSON.stringify(SCHEMA) }] },
      contents: [{ role: 'user', parts: [{ text: 'Données :\n' + JSON.stringify(donnees, null, 2) }] }],
      // Sortie JSON imposée ; température modérée pour un ton naturel sans inventer
      generationConfig: { responseMimeType: 'application/json', temperature: 0.7 },
    },
  };
}

// Une requête IA par inscription à rappeler (seules les données utiles sont envoyées)
return $input.all()
  .filter(item => item.json.inscriptionId)
  .map(item => {
    const r = item.json;
    const m = r.mission;
    return { json: { ...r, requeteIA: requeteIA({
      prenom: r.prenom,
      mission: m.titre, association: m.association, description: m.description,
      debut: m.dateDebut, fin: m.dateFin, lieu: m.adresse || m.ville, competences: m.competences,
    }) } };
  });

// Gabarit HTML CountMeIn (même charte que les e-mails envoyés par le backend)
function esc(s) {
  return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}
function gabarit({ badge, couleur, couleurTexte, prenom, titre, paragraphes, details, blocs, bouton, lien }) {
  const corps = (paragraphes || []).map(p =>
    `<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#444;">${esc(p)}</p>`).join('');
  const lignes = Object.entries(details || {}).filter(([, v]) => v).map(([k, v]) =>
    `<tr><td style="padding:7px 0;font-size:13px;color:#777;width:110px;vertical-align:top;">${esc(k)}</td>` +
    `<td style="padding:7px 0;font-size:14px;font-weight:700;color:#1a1a1a;">${esc(v)}</td></tr>`).join('');
  const encadre = lignes ? `<table cellpadding="0" cellspacing="0" style="width:100%;margin-top:8px;border:2px solid #1a1a1a;border-left:8px solid ${couleur};border-radius:10px;"><tr><td style="padding:12px 18px;"><table cellpadding="0" cellspacing="0" style="width:100%;">${lignes}</table></td></tr></table>` : '';
  const btn = lien ? `<table cellpadding="0" cellspacing="0" style="margin:24px 0 8px;"><tr><td style="background:${couleur};border:2px solid #1a1a1a;border-radius:10px;box-shadow:3px 3px 0 #1a1a1a;"><a href="${esc(lien)}" style="display:inline-block;padding:13px 26px;font-size:15px;font-weight:800;color:${couleurTexte};text-decoration:none;">${esc(bouton)} →</a></td></tr></table>` : '';
  return `<!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8"></head>
<body style="margin:0;padding:0;background:#f5f0e8;font-family:'Helvetica Neue',Arial,sans-serif;">
<table width="100%" cellpadding="0" cellspacing="0" style="background:#f5f0e8;padding:40px 20px;"><tr><td align="center">
<table width="600" cellpadding="0" cellspacing="0" style="max-width:600px;background:#fff;border:3px solid #1a1a1a;border-radius:16px;overflow:hidden;box-shadow:6px 6px 0 #1a1a1a;">
<tr><td style="background:#f7c948;border-bottom:3px solid #1a1a1a;padding:22px 40px;">
<h1 style="margin:0;font-size:26px;font-weight:900;color:#1a1a1a;">CountMeIn</h1>
<p style="margin:4px 0 0;font-size:13px;font-weight:600;color:#1a1a1a;opacity:0.7;">Connecter · Soutenir · Agir</p></td></tr>
<tr><td style="padding:34px 40px 30px;">
<span style="display:inline-block;padding:5px 12px;background:${couleur};color:${couleurTexte};border:2px solid #1a1a1a;border-radius:999px;font-size:12px;font-weight:800;text-transform:uppercase;">${esc(badge)}</span>
<p style="margin:20px 0 6px;font-size:14px;color:#777;">Bonjour ${esc(prenom)},</p>
<h2 style="margin:0 0 14px;font-size:23px;font-weight:900;color:#1a1a1a;line-height:1.25;">${esc(titre)}</h2>
${corps}${encadre}${blocs || ''}${btn}
</td></tr>
<tr><td style="background:#1a1a1a;padding:18px 40px;"><p style="margin:0;font-size:12px;color:#aaa;text-align:center;line-height:1.6;">
© ${new Date().getFullYear()} CountMeIn — Plateforme de bénévolat au Maroc<br>Vous pouvez désactiver ces e-mails depuis la page Notifications de votre espace.</p></td></tr>
</table></td></tr></table></body></html>`;
}

// Lit la réponse de Gemini : JSON conforme au schéma, sinon null (→ texte de secours, F48)
function lireReponseIA(reponse) {
  const candidat = reponse && (reponse.candidates || [])[0];
  if (!candidat || candidat.finishReason !== 'STOP') return null;
  const texte = ((candidat.content || {}).parts || []).map(p => p.text || '').join('');
  try {
    const json = JSON.parse(texte.replace(/^```(?:json)?\s*|\s*```$/g, ''));
    return json && json.sujet ? json : null;
  } catch (e) { return null; }
}

const sources = $('Preparer la requete IA').all();
return $input.all().map((item, i) => {
  const r = sources[i].json;
  const m = r.mission;
  const ia = lireReponseIA(item.json) || {
    // Texte standard si l'IA est indisponible (F48)
    sujet: `Rappel : ${m.titre} commence bientôt`,
    titre: 'Ta mission commence bientôt',
    paragraphes: [
      `Petit rappel : la mission « ${m.titre} » avec ${m.association} commence ${m.dateDebut.toLowerCase()}.`,
      "Si tu ne peux plus venir, préviens l'association au plus vite pour qu'elle puisse s'organiser.",
    ],
  };
  return { json: {
    inscriptionId: r.inscriptionId,
    email: r.email,
    sujet: ia.sujet,
    html: gabarit({
      badge: 'Rappel', couleur: '#EEC22A', couleurTexte: '#1a1a1a', prenom: r.prenom,
      titre: ia.titre, paragraphes: ia.paragraphes,
      details: { Mission: m.titre, Association: m.association, Date: m.dateDebut, Lieu: m.adresse || m.ville },
      bouton: 'Voir la mission', lien: m.lien,
    }),
  } };
});
